function enrichCampaignMaps(maps){
 for(let i=1;i<=40;i++){
  const id=`stage${String(i).padStart(2,'0')}`,m=maps[id],identity=MAP_IDENTITIES[id];if(!m||!identity)continue;
  const kit=BIOME_KITS[identity.biome]||BIOME_KITS.meadow;
  m.identity={...identity,chapter:Math.ceil(i/5),level:i};
  m.biome=m.biome||identity.biome;
  m.environment={...battlefieldClone(kit),...(m.environment||{}),groundName:identity.ground,roadName:identity.road,landmark:identity.landmark,signature:identity.signature,tactical:identity.tactical,tags:[...identity.tags]};
  m.visualFeatures=[...(FEATURE_PRESETS[id]||[]),...(m.visualFeatures||[])];
  m.preview={title:identity.name,subtitle:kit.label,tactical:identity.tactical,signature:identity.signature,tags:[...identity.tags]};
 }
 return maps;
}

function mapIdentityFor(id,map){return map?.identity||MAP_IDENTITIES[id]||{name:map?.name||id,biome:map?.biome||'meadow',tactical:'实验地图',signature:'自定义战场',tags:[]};}

function drawMapPreview(canvas,map,{showSlots=true,label=true}={}){
 if(!canvas||!map)return;const c=canvas.getContext('2d'),W=canvas.width||480,H=canvas.height||255,sx=W/1280,sy=H/680,env=map.environment||BIOME_KITS[map.biome]||BIOME_KITS.meadow;
 const grad=c.createLinearGradient(0,0,0,H);grad.addColorStop(0,env.ground2||'#4d5d4a');grad.addColorStop(1,env.ground||'#303a32');c.fillStyle=grad;c.fillRect(0,0,W,H);
 c.save();c.globalAlpha=.15;c.fillStyle=env.detail||'#fff';for(let i=0;i<45;i++){const x=((i*97+31)%1280)*sx,y=((i*61+53)%680)*sy,r=(2+i%3)*Math.min(sx,sy)*2;c.beginPath();c.arc(x,y,Math.max(1,r),0,Math.PI*2);c.fill()}c.restore();
 const paths=Object.values(map.paths||{main:map.path||[]});for(const p of paths){if(!p?.length)continue;c.lineCap='round';c.lineJoin='round';const draw=()=>{c.beginPath();c.moveTo(p[0][0]*sx,p[0][1]*sy);for(const q of p.slice(1))c.lineTo(q[0]*sx,q[1]*sy)};c.strokeStyle=env.edge||'#352c29';c.lineWidth=Math.max(7,70*sx);draw();c.stroke();c.strokeStyle=env.road||'#886b54';c.lineWidth=Math.max(5,52*sx);draw();c.stroke();c.strokeStyle=env.detail||'#d4b98b';c.globalAlpha=.45;c.lineWidth=Math.max(1,2*sx);c.setLineDash([8*sx,12*sx]);draw();c.stroke();c.setLineDash([]);c.globalAlpha=1}
 const feats=map.visualFeatures||[];for(const f of feats.slice(0,12)){const x=f.x*sx,y=f.y*sy;if(!Number.isFinite(x)||!Number.isFinite(y))continue;c.fillStyle=env.detail||'#d7b37a';c.strokeStyle='rgba(25,20,22,.8)';c.lineWidth=1.5;c.beginPath();c.arc(x,y,Math.max(3,(f.r||24)*sx*.45),0,Math.PI*2);c.fill();c.stroke()}
 if(showSlots)for(const s of (map.manualSlots||[])){c.fillStyle=s.quality==='gold'?'#f3cf72':'#d5b37b';c.strokeStyle='#2c2525';c.lineWidth=1.5;c.beginPath();c.arc(s.x*sx,s.y*sy,Math.max(2.5,10*sx),0,Math.PI*2);c.fill();c.stroke()}
 const entrances=paths.map(p=>p?.[0]).filter(Boolean),exit=map.path?.at?.(-1);c.fillStyle='#8bd4a8';for(const p of entrances){c.beginPath();c.arc(p[0]*sx,p[1]*sy,Math.max(4,13*sx),0,Math.PI*2);c.fill()}if(exit){c.fillStyle='#ffcf83';c.fillRect(exit[0]*sx-5,exit[1]*sy-5,10,10)}
 if(label){c.fillStyle='rgba(15,13,17,.72)';c.fillRect(0,H-30,W,30);c.fillStyle='#fff0d0';c.font=`700 ${Math.max(11,14*sx*2)}px sans-serif`;c.textAlign='left';c.fillText(map.name||map.identity?.name||'Battlefield',12,H-10)}
}

function validateForgeMap(map){
 const errors=[],warnings=[],paths=map?.paths||{};const entries=Object.entries(paths);if(!map?.name?.trim())warnings.push('建议为地图命名');if(entries.length<1)errors.push('至少需要一条路线');if(entries.length>3)errors.push('第一版工坊最多支持三条路线');
 for(const [id,p] of entries){if(!Array.isArray(p)||p.length<2){errors.push(`${id} 至少需要 Spawn 与 Core 两个节点`);continue}for(const [x,y] of p)if(!Number.isFinite(x)||!Number.isFinite(y)||x<20||x>1260||y<20||y>660)errors.push(`${id} 存在越界节点`);for(let i=1;i<p.length;i++)if(Math.hypot(p[i][0]-p[i-1][0],p[i][1]-p[i-1][1])<28)warnings.push(`${id} 有过短路段，可能难以阅读`)}
 if(entries.length){const ends=entries.map(([,p])=>p?.at?.(-1)).filter(Boolean);if(ends.length>1&&ends.some(e=>Math.hypot(e[0]-ends[0][0],e[1]-ends[0][1])>30))warnings.push('多路线 Core 不一致：允许实验，但正式地图建议共享或明确双核心语义')}
 const slots=map?.manualSlots||[];if(slots.length<4)warnings.push('塔位过少：建议至少放置 4 个实验塔位');if(slots.length>30)warnings.push('塔位过多：可能削弱空间资源感');
 const distSeg=(x,y,a,b)=>{const vx=b[0]-a[0],vy=b[1]-a[1],l=vx*vx+vy*vy||1,t=Math.max(0,Math.min(1,((x-a[0])*vx+(y-a[1])*vy)/l));return Math.hypot(x-(a[0]+t*vx),y-(a[1]+t*vy))};
 for(const [i,s] of slots.entries()){if(!Number.isFinite(s.x)||!Number.isFinite(s.y)||s.x<25||s.x>1255||s.y<25||s.y>655)errors.push(`塔位 ${i+1} 越界`);let near=Infinity;for(const [,p] of entries)for(let j=1;j<p.length;j++)near=Math.min(near,distSeg(s.x,s.y,p[j-1],p[j]));if(near<48)warnings.push(`塔位 ${i+1} 距道路过近，实战加载时可能被过滤`)}
 const portals=(map?.visualFeatures||[]).filter(f=>f.type==='PORTAL');if(portals.length===1)errors.push('Portal 必须至少成对出现');if(portals.length>0&&portals.length%2!==0)warnings.push('Portal 数量为奇数：建议成对布置以便玩家理解连接关系');
 for(const f of map?.visualFeatures||[])if(['BRIDGE','TUNNEL','PORTAL','GATE','FACILITY','FORGE_BEACON'].includes(f.type)&&(!Number.isFinite(f.x)||!Number.isFinite(f.y)))errors.push(`${f.type} 缺少有效坐标`);
 return{ok:errors.length===0,errors,warnings,routeCount:entries.length,slotCount:slots.length,portalCount:portals.length};
}

function makeForgeTemplate(name='我的战场',biome='forge'){
 const path=[[70,340],[250,340],[420,180],[650,180],[820,500],[1050,500],[1210,340]];
 return{name,biome,design:'player-forge',routePattern:'single',palette:['#364249','#52636a','#242c30'],path,paths:{main:path.map(p=>[...p])},towerSlotBudget:16,manualSlots:[{id:'f0',x:340,y:280,type:'anchor',quality:'gold',manual:true},{id:'f1',x:530,y:310,type:'normal',quality:'standard',manual:true},{id:'f2',x:740,y:350,type:'anchor',quality:'gold',manual:true},{id:'f3',x:940,y:410,type:'normal',quality:'standard',manual:true}],visualFeatures:[{type:'FORGE_BEACON',x:650,y:340}],environment:{...battlefieldClone(BIOME_KITS[biome]||BIOME_KITS.forge),groundName:'自定义地表',roadName:'自定义道路',landmark:'战场工坊信标',signature:'玩家设计地图',tactical:'自由实验',tags:['FORGE']},identity:{name,biome,tactical:'自由实验',signature:'玩家设计地图',road:'自定义道路',ground:'自定义地表',landmark:'战场工坊信标',tags:['FORGE']}};
}

function normalizeForgeMap(raw){const m=battlefieldClone(raw||makeForgeTemplate());m.name=String(m.name||'我的战场').slice(0,28);m.biome=BIOME_KITS[m.biome]?m.biome:'forge';m.paths=m.paths&&typeof m.paths==='object'?m.paths:{main:Array.isArray(m.path)?m.path:[[70,340],[1210,340]]};if(!m.paths.main)m.paths.main=Object.values(m.paths)[0]||[[70,340],[1210,340]];m.path=m.paths.main;m.manualSlots=(m.manualSlots||[]).map((s,i)=>({...s,id:s.id||`f${i}`,manual:true}));m.towerSlotBudget=Math.max(8,Math.min(30,m.towerSlotBudget||Math.max(12,m.manualSlots.length)));const previousEnv=m.environment||{};const kit=battlefieldClone(BIOME_KITS[m.biome]);m.environment={...kit,groundName:previousEnv.groundName||'自定义地表',roadName:previousEnv.roadName||'自定义道路',landmark:previousEnv.landmark||'战场工坊信标',signature:'玩家设计地图',tactical:'自由实验',tags:['FORGE']};m.identity={name:m.name,biome:m.biome,tactical:'自由实验',signature:'玩家设计地图',road:m.environment.roadName||'自定义道路',ground:m.environment.groundName||'自定义地表',landmark:m.environment.landmark||'自定义地标',tags:['FORGE']};return m;}


