const LEVELS={
 1:{factor:1,size:.72,label:'基础'},
 2:{factor:1.42,size:.79,label:'强化'},
 3:{factor:2.02,size:.87,label:'核心'},
 4:{factor:2.82,size:.97,label:'高级'},
 5:{factor:3.85,size:1.10,label:'终极'},
};
const LEVEL_LIST=[1,2,3,4,5];
const ECONOMY={
 build:{fire:100,water:95,wind:90,earth:110,light:115,dark:115},
 upgradeBase:[0,0,120,195,315,520], // index = target level
 sellRatio:{easy:.75,standard:.65,expert:.58},
 waveRewardBase:85,
 earlyGoldPerSecond:15,
 rushBonus:90,
};
const elementFactor=e=>(ECONOMY.build[e]||100)/100;
function baseBuildCost(element){return ECONOMY.build[element]??100}
function baseUpgradeCost(element,from,to=from+1){if(to!==from+1||to<2||to>5)return Infinity;return Math.round(ECONOMY.upgradeBase[to]*elementFactor(element))}
function fusionUpgradeCost(fusionId,from,to=from+1){const f=FUSION_BY_ID[fusionId];if(!f)return Infinity;return f.elements.reduce((sum,e)=>sum+baseUpgradeCost(e,from,to),0)}
function towerUpgradeCost(tower){if(!tower||tower.level>=5)return Infinity;return tower.kind==='base'?baseUpgradeCost(tower.element,tower.level):fusionUpgradeCost(tower.fusion,tower.level)}
function sellValue(tower,difficulty='standard'){return Math.floor((tower?.invested||0)*(ECONOMY.sellRatio[difficulty]||ECONOMY.sellRatio.standard))}
// compatibility names used by archived tooling; campaign v5 never directly builds higher levels.
function directBuildCost(level,element='fire'){let total=baseBuildCost(element);for(let l=1;l<level;l++)total+=baseUpgradeCost(element,l);return total}
function upgradeCost(from,to=from+1,element='fire'){return baseUpgradeCost(element,from,to)}

