const fusion=(id,name,elements,color,accent,dmg,interval,range,role,desc,mechanic,story,tags=[])=>({id,name,elements,color,accent,dmg,interval,range,role,desc,mechanic,story,tags,sprite:'tower_'+id});
const FUSIONS={
 'fire+water':fusion('steam','蒸汽塔',['fire','water'],'#76C7D6','#F5FDFF',51,.95,220,'直线贯穿 / 湿热','高压蒸汽贯穿多名敌人；湿热目标更容易受到元素连锁。','pierce','第一座蒸汽塔诞生于一次锅炉爆炸。火匠和水法师争论了三天是谁的责任，第四天他们发现爆炸后的装置意外非常能打。',['贯穿','状态','道路控制']),
 'fire+wind':fusion('blast','爆炎塔',['fire','wind'],'#FF7048','#FFD39E',58,.72,198,'连锁爆炸','火箭命中造成范围爆炸；击杀会继续引爆附近敌人。','chain','爆炎塔的设计原则十分朴素：如果一枚火箭不够，那就让第一枚火箭替第二枚火箭点火。',['爆炸','连锁','清场']),
 'earth+fire':fusion('lava','熔岩塔',['earth','fire'],'#D95C35','#FFC06A',65,1.02,202,'熔岩区域 / 破甲','命中留下熔岩池，持续烧灼并逐渐削弱重甲。','lava','熔岩塔周围严禁晾衣服。不是因为危险，而是因为所有人都受不了衣服上永远散不掉的硫磺味。',['区域','破甲','持续']),
 'fire+light':fusion('holyfire','圣焰塔',['fire','light'],'#FFB84D','#FFF6C4',61,.82,222,'净化 / 圣焰爆发','对护盾与高威胁单位效率更高，击破护盾时触发圣焰波。','holy','圣焰塔的维护条例长达八十七页，其中有六页专门说明“神圣火焰同样会烫伤维护人员”。',['净化','护盾克制','爆发']),
 'dark+fire':fusion('hellfire','狱火塔',['dark','fire'],'#B64B5C','#FF9A72',72,.94,204,'魂火 / 城堡护盾','持续积累魂火；爆发时对精英造成高伤并为城堡补充护盾。','hell','没人承认自己是第一位提出“把诅咒塞进炉子里烧”的炼金师，但狱火塔的存在说明总有人真的试过。',['精英','护盾','魂火']),
 'water+wind':fusion('frost','冰霜塔',['water','wind'],'#8BE8FF','#F2FEFF',43,.78,214,'冻结领域','连续寒气会把减速逐步升级为完全冻结。','frost','冰霜塔附近的士兵从来不用担心饮料变热，唯一的问题是偶尔连杯子也会冻在桌面上。',['冻结','控场','区域']),
 'earth+water':fusion('swamp','沼泽塔',['earth','water'],'#6FA36F','#CDE59B',39,1.05,218,'道路改造 / 减速破甲','攻击制造沼泽，使范围内敌人持续减速并降低护甲。','swamp','沼泽塔的设计师坚持这叫“可控战术湿地”。守军则坚持它就是一大片非常有效的泥。',['减速','破甲','道路']),
 'light+water':fusion('heal','治愈塔',['light','water'],'#7EE0C0','#FFF8BE',0,1.20,225,'支援 / 修复','周期性强化附近防御塔，并在城堡受损时缓慢修复。','heal','治愈塔不参加谁的伤害最高这种争论。它通常只是在旁边安静地把所有人修好。',['支援','治疗','强化']),
 'dark+water':fusion('poison','毒雾塔',['dark','water'],'#9762C8','#C8E6D3',37,1.02,216,'毒雾区域','制造持续毒雾，敌人停留越久承受的伤害越多。','poison','毒雾塔的瓶子上贴着醒目的“不要喝”。据说这张标签是在第三次事故之后才加上的。',['毒雾','区域','持续']),
 'earth+wind':fusion('sand','沙暴塔',['earth','wind'],'#C8A14F','#F2D998',42,.86,216,'沙暴 / 飞行压制','制造沙暴减速、破甲，并额外克制飞行敌人。','sand','沙暴塔能把飞行怪吹到地上，也能把守军刚扫干净的城墙重新铺满一层沙。',['飞行克制','破甲','减速']),
 'light+wind':fusion('flash','疾光塔',['light','wind'],'#E8E06A','#FFFFFF',44,.42,230,'高速暴击 / 折射','极高攻速；连续命中提高暴击率，暴击会折射到附近敌人。','flash','疾光塔快到让记录员很难统计它到底打了多少次，于是后来大家干脆相信计数器。',['高频','暴击','折射']),
 'dark+wind':fusion('shadowwind','影风塔',['dark','wind'],'#6155A7','#BDA9FF',55,.62,224,'刺杀 / 高威胁优先','优先攻击萨满等高威胁单位，并无视大量护甲。','assassin','影风塔从来不打最靠前的敌人。它似乎总能挑出队伍里那个“最该先消失”的家伙。',['刺杀','高威胁','破甲']),
 'earth+light':fusion('crystal','晶岩塔',['earth','light'],'#D5B97B','#FFF0BC',71,1.16,210,'震荡 / 打断','重击产生晶体冲击波，可短暂眩晕普通敌人并打断 Boss 读条。','stun','晶岩塔的晶体在撞击时会发出非常漂亮的声音。遗憾的是，敌人通常来不及欣赏第二次。',['打断','眩晕','重击']),
 'dark+earth':fusion('nether','冥石塔',['dark','earth'],'#824B8A','#DDA2DF',82,1.18,202,'碎裂 / Boss 处决','重击积累碎裂并大幅破甲；低血量重甲目标会遭处决。','execute','冥石塔的石材来源一直是军械库不愿公开的秘密。唯一确定的是，它们敲在铁甲上非常响。',['处决','Boss','破甲']),
 'dark+light':fusion('chaos','混沌塔',['dark','light'],'#C07BD6','#FFF1FF',64,.86,216,'随机多效果 / 高上限','攻击随机触发爆裂、冻结、破甲或折射；混沌积累后进入高能状态。','chaos','光与暗的研究员唯一达成一致的事情，就是混沌塔绝对不应该被任何一个人单独负责。',['随机','高上限','多效果']),
};
const FUSION_BY_ID=Object.fromEntries(Object.values(FUSIONS).map(x=>[x.id,x]));
function fusionFor(a,b){return FUSIONS[[a,b].sort().join('+')]||null;}



