const V9_LEVEL_NAMES=['断旗外郭','三壕推进线','反应炉封锁区','灰河桥群','黑铁攻城门','腐根回廊','毒沼双潮','巨根迷宫','掘地盆地','母巢心脏','浮空断层','雷桥交错','相位岛链','六相潮汐环','棱镜断界','三门围城','活闸回廊','攻城铸造场','王座螺旋阶','裂隙王冠'];
const V9_BOSSES={25:'ironmarshal',30:'broodmother',35:'prismarch',40:'riftking'};
for(let id=21;id<=40;id++){
 const chapter=Math.ceil(id/5),boss=V9_BOSSES[id]||null;
 CAMPAIGN_LEVELS[id]={id,name:V9_LEVEL_NAMES[id-21],map:`stage${id}`,waveCount:Math.min(18,14+Math.floor((id-21)/4)),maxTowerLevel:5,elements:Object.keys(ELEMENTS),fusionCount:15,skillCount:4,startingGold:1780+(id-21)*82,boss,starThreat:6+Math.floor((id-21)/4),campaign:2,chapter,desc:id<=25?'第二战役：Riftbound 正规军与战争设施。':id<=30?'腐化荒野：巢穴、再生与多点压力。':id<=35?'元素崩解：异常抗性、飞行与相位战。':'裂隙堡垒：攻城单位、多入口与最终战争。'};
}

function levelConfig(id){return CAMPAIGN_LEVELS[id]||CAMPAIGN_LEVELS[1]}
function unlockedFusionIds(levelId){return FUSION_UNLOCK_ORDER.slice(0,levelConfig(levelId).fusionCount)}
function unlockedSkills(levelId){return Object.keys(SKILLS).slice(0,levelConfig(levelId).skillCount)}

const MINIONS=['slime','rabbit','bat','crawler','spider','thief'];
const ELITES=['turtle','bomber','wolf','juggernaut','eater','burrower','revenant','riftguard','saboteur','marksman'];
const COMMANDERS=['shaman','shieldmage','silencer','summoner','chrono','banner','artillery','warlord','fieldalchemist','disruptor','tactician'];
function waveRoster(levelId,waveIndex){
 const cfg=levelConfig(levelId),progress=cfg.waveCount<=1?1:waveIndex/(cfg.waveCount-1),minions=MINIONS.slice(0,Math.min(MINIONS.length,2+Math.ceil(levelId/3)));
 const elites=levelId<3?[]:ELITES.slice(0,Math.min(ELITES.length,1+Math.floor((levelId-3)/2)));
 const commanders=levelId<6?[]:COMMANDERS.slice(0,Math.min(COMMANDERS.length,1+Math.floor((levelId-6)/2)));
 // Campaign waves are deterministic: tactical intelligence must describe exactly what will arrive.
 let seed=((levelId*73856093)^((waveIndex+1)*19349663)^0x9e3779b9)>>>0;const R=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return(seed>>>0)/4294967296};
 const n=Math.min(90,Math.round(14+levelId*1.4+waveIndex*(1.8+levelId*.08))),arr=[];
 for(let i=0;i<n;i++){const r=R();if(commanders.length&&progress>.35&&r<.05+progress*.10)arr.push(commanders[Math.floor(R()*commanders.length)]);else if(elites.length&&r<.16+progress*.18)arr.push(elites[Math.floor(R()*elites.length)]);else arr.push(minions[Math.floor(R()*minions.length)])}
 // Authored synergy packets ensure waves ask recognizable strategic questions instead of being random bags of stats.
 if(levelId>=6&&waveIndex>=2){const packet=waveIndex%4;if(packet===0&&ENEMIES.shaman){arr.push('shaman');if(ENEMIES.turtle)arr.push('turtle','turtle')}else if(packet===1&&ENEMIES.shieldmage){arr.push('shieldmage');if(ENEMIES.wolf)arr.push('wolf','wolf')}else if(packet===2&&ENEMIES.silencer){arr.push('silencer');if(ENEMIES.bomber)arr.push('bomber','bomber')}else if(packet===3&&ENEMIES.summoner){arr.push('summoner');if(ENEMIES.crawler)arr.push('crawler','crawler','crawler')}}
 if(levelId>=12&&progress>.55){arr.push(waveIndex%2?'chrono':'banner');if(ENEMIES.juggernaut)arr.push('juggernaut')}
 if(levelId>=16&&progress>.72){arr.push(waveIndex%2?'warlord':'artillery');if(ENEMIES.eater)arr.push('eater')}
 // Riftbound are substitutions rather than extra bodies: new tactical identity without inflating the legacy pressure budget.
 if(levelId>=13&&waveIndex>=3&&waveIndex%4===1){const ei=arr.findIndex(x=>ELITES.includes(x));if(ei>=0)arr[ei]='riftguard';const ci=arr.findIndex(x=>COMMANDERS.includes(x));if(ci>=0)arr[ci]='fieldalchemist';if(levelId>=16){const ci2=arr.findIndex((x,i)=>i!==ci&&COMMANDERS.includes(x));if(ci2>=0)arr[ci2]='disruptor'}}
 if(levelId>=17&&progress>.5&&waveIndex%3===0){const ci=arr.findIndex(x=>COMMANDERS.includes(x));if(ci>=0)arr[ci]='tactician';const ei=arr.findIndex(x=>ELITES.includes(x));if(ei>=0)arr[ei]='saboteur';if(progress>.75){const ei2=arr.findIndex((x,i)=>i!==ei&&ELITES.includes(x));if(ei2>=0)arr[ei2]='marksman'}}

 if(levelId>=21){
   const chapter=Math.ceil(levelId/5),late=progress>.55,final=progress>.78;
   if(chapter===5){
     // Riftbound正规军：步兵只是载体，真正压力来自盾卫、炼金支援、工程和指挥链。
     for(let i=0;i<Math.min(12,4+Math.floor(waveIndex/2));i++)arr.push('rb_line');
     if(waveIndex%2===0)arr.push('rb_guard');
     if(late)arr.push(waveIndex%3===0?'rb_alchemist':'rb_engineer');
     if(final)arr.push('rb_commander',waveIndex%2?'rb_sniper':'rb_siegewalker');
   }else if(chapter===6){
     for(let i=0;i<Math.min(16,6+waveIndex);i++)arr.push('beast_swarmling');
     arr.push(waveIndex%2?'beast_burrower':'beast_carrier');
     if(late)arr.push('beast_regenerator','beast_predator');
     if(final)arr.push('beast_broodguard');
   }else if(chapter===7){
     for(let i=0;i<Math.min(10,3+Math.floor(waveIndex/2));i++)arr.push('aberr_spark');
     const packet=['aberr_flame','aberr_frost','aberr_storm','aberr_stone'];arr.push(packet[waveIndex%packet.length]);
     if(late)arr.push(waveIndex%2?'aberr_light':'aberr_void');
     if(final)arr.push('aberr_stone','aberr_storm');
   }else if(chapter>=8){
     for(let i=0;i<Math.min(8,3+Math.floor(waveIndex/2));i++)arr.push(i%2?'rb_line':'beast_swarmling');
     arr.push(waveIndex%3===0?'siege_mortar':waveIndex%3===1?'siege_saboteur':'siege_beast');
     if(late)arr.push('siege_engineer',waveIndex%2?'rb_commander':'aberr_void');
     if(final)arr.push('rb_siegewalker','aberr_stone');
   }
 }
 if(cfg.boss&&waveIndex===cfg.waveCount-1)arr.push('BOSS:'+cfg.boss);
 return arr;
}

// compatibility for archived tests. v5 campaign waves are generated per selected level.
const WAVES=Array.from({length:levelConfig(10).waveCount},(_,i)=>waveRoster(10,i));


// ---- storage.js ----
const nativeInvoke=()=>globalThis.__TAURI__?.core?.invoke||null;
function webStore(){try{return globalThis.localStorage||null}catch{return null}}
const APP_STORAGE={
  hydrated:false,
  async hydrate(){
    const invoke=nativeInvoke();if(!invoke){this.hydrated=true;return false}
    try{const data=await invoke('load_native_store');const s=webStore();if(s&&data&&typeof data==='object')for(const [k,v] of Object.entries(data))if(typeof v==='string')s.setItem(k,v);this.hydrated=true;return true}catch(err){console.warn('[EFTD native storage hydrate]',err);this.hydrated=true;return false}
  },
  getItem(key){return webStore()?.getItem(key)??null},
  setItem(key,value){const v=String(value);try{webStore()?.setItem(key,v)}catch{};const invoke=nativeInvoke();if(invoke)invoke('save_native_value',{key,value:v}).catch(err=>console.warn('[EFTD native storage save]',err))},
  removeItem(key){try{webStore()?.removeItem(key)}catch{};const invoke=nativeInvoke();if(invoke)invoke('remove_native_value',{key}).catch(err=>console.warn('[EFTD native storage remove]',err))}
};


// ---- access.js ----

const MAX_CAMPAIGN_LEVEL=40;

function hasAccess(profileStore,featureId,context={}){
  if(profileStore?.isDeveloper?.()) return true;
  const level=Math.max(1,Math.min(MAX_CAMPAIGN_LEVEL,+context.levelId||1));
  const cfg=levelConfig(level);
  const [kind,id]=String(featureId||'').split(':');
  if(kind==='level') return (+id||1) <= (profileStore?.active?.campaign?.unlocked||1);
  if(kind==='element') return cfg.elements.includes(id);
  if(kind==='fusion') return unlockedFusionIds(level).includes(id);
  if(kind==='skill') return unlockedSkills(level).includes(id);
  if(kind==='towerLevel') return (+id||1) <= cfg.maxTowerLevel;
  if(kind==='mode') return !!profileStore?.active?.modeUnlocks?.[id];
  if(kind==='boss'||kind==='enemy'||kind==='map') return true;
  return false;
}

function techFor(profileStore,mode,levelId){
  if(profileStore?.isDeveloper?.() || ['creative','endless','bossrush','grand'].includes(mode)){
    return {maxTowerLevel:5,elements:Object.keys(ELEMENTS),fusionIds:Object.keys(FUSION_BY_ID),skillIds:Object.keys(SKILLS),developerOverride:!!profileStore?.isDeveloper?.()};
  }
  const c=levelConfig(levelId);
  return {maxTowerLevel:c.maxTowerLevel,elements:[...c.elements],fusionIds:unlockedFusionIds(levelId),skillIds:unlockedSkills(levelId),developerOverride:false};
}


// ---- map_design.js ----

const PATH_SEMANTIC_TYPES=new Set(['MERGE','SPLIT','INTERSECTION','CROSSOVER','BRIDGE','TUNNEL','PORTAL','GATE']);
const d=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]);
function cross(a,b,c,d2){return (b[0]-a[0])*(d2[1]-c[1])-(b[1]-a[1])*(d2[0]-c[0])}
function segmentIntersection(a,b,c,d2){const den=cross(a,b,c,d2);if(Math.abs(den)<1e-7)return null;const t=cross(c,d2,c,a)/den,u=cross(a,b,a,c)/den;if(t<=1e-4||t>=.9999||u<=1e-4||u>=.9999)return null;return[a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1])]}
function nearFeature(fs,pt,r=52){return fs.find(f=>PATH_SEMANTIC_TYPES.has(f.type)&&d([f.x||0,f.y||0],pt)<=r)}

// Converts geometric relationships into explicit rendering semantics. Declared map features always win;
// inferred pieces exist to guarantee that procedural/content-authored paths never fall back to raw line overlap.
function semanticFeatures(map){
  const declared=[...(map?.visualFeatures||[])],out=[...declared],paths=Object.entries(map?.paths||{main:map?.path||[]});
  const add=(f)=>{if(!nearFeature(out,[f.x,f.y],34))out.push({...f,inferred:true})};
  for(let i=0;i<paths.length;i++)for(let j=i+1;j<paths.length;j++){
    const [idA,a]=paths[i],[idB,b]=paths[j];
    for(let ia=0;ia<a.length-1;ia++)for(let ib=0;ib<b.length-1;ib++){
      const pt=segmentIntersection(a[ia],a[ia+1],b[ib],b[ib+1]);
      if(pt&&!nearFeature(out,pt))add({type:'BRIDGE',x:pt[0],y:pt[1],over:(ia+ib)%2?idA:idB,paths:[idA,idB]});
    }
    const pointsA=a.slice(1,-1),pointsB=b.slice(1,-1);
    for(const p of pointsA)for(const q of pointsB)if(d(p,q)<2&&!nearFeature(out,p))add({type:'INTERSECTION',x:p[0],y:p[1],paths:[idA,idB]});
  }
  return out;
}

function validatePathSemantics(map){
  const errors=[],features=semanticFeatures(map),paths=Object.entries(map?.paths||{main:map?.path||[]});
  for(let i=0;i<paths.length;i++)for(let j=i+1;j<paths.length;j++){
    const [idA,a]=paths[i],[idB,b]=paths[j];
    for(let ia=0;ia<a.length-1;ia++)for(let ib=0;ib<b.length-1;ib++){
      const pt=segmentIntersection(a[ia],a[ia+1],b[ib],b[ib+1]);
      if(pt&&!nearFeature(features,pt))errors.push({type:'UNTYPED_CROSSING',paths:[idA,idB],point:pt});
    }
  }
  const inferred=features.filter(f=>f.inferred);
  return{ok:errors.length===0,errors,semanticCount:features.filter(f=>PATH_SEMANTIC_TYPES.has(f.type)).length,inferredCount:inferred.length};
}
function towerSlotMetrics(map){return{routeCount:Object.keys(map?.paths||{main:map?.path||[]}).length,slotBudget:map?.towerSlotBudget??null,manualSlots:(map?.manualSlots||[]).length,semanticFeatures:semanticFeatures(map).filter(f=>PATH_SEMANTIC_TYPES.has(f.type)).length,design:map?.design||'legacy'}}
function validateCampaign2Maps(){const results={};for(let id=21;id<=40;id++){const key=`stage${String(id).padStart(2,'0')}`,map=MAPS[key];results[key]={...validatePathSemantics(map),metrics:towerSlotMetrics(map)}}return results}


