const REVEAL_STATE={HIDDEN:'HIDDEN',SILHOUETTE:'SILHOUETTE',NAME_ONLY:'NAME_ONLY',DISCOVERED:'DISCOVERED',MASTERED:'MASTERED'};
function getRevealState(content,profileStore){
 const ps=profileStore,p=ps?.active||ps||{};if(ps?.isDeveloper?.())return REVEAL_STATE.MASTERED;
 const unlocked=content?.id&&ps?.achievementUnlocked?.(content.id);if(unlocked)return REVEAL_STATE.MASTERED;
 const tags=content?.spoilerTags||[];
 for(const tag of tags){const parts=String(tag).split(':'),kind=parts.shift(),id=parts.join(':');if(kind==='boss'&&!p.codex?.bosses?.includes(id))return REVEAL_STATE.HIDDEN;if(kind==='enemy'&&!p.codex?.enemies?.includes(id))return REVEAL_STATE.HIDDEN;if(kind==='fusion'&&!p.discoveredFusions?.includes(id))return REVEAL_STATE.HIDDEN;if(kind==='chapter'&&!p.campaign?.completedChapters?.includes(+id))return REVEAL_STATE.HIDDEN;if(kind==='system'&&!p.unlockedSystems?.includes(id))return REVEAL_STATE.HIDDEN}
 if(content?.hidden&&!unlocked)return REVEAL_STATE.HIDDEN;return REVEAL_STATE.DISCOVERED
}
function canReveal(content,profileStore){return getRevealState(content,profileStore)!==REVEAL_STATE.HIDDEN}

