const BATTLE_SNAPSHOT_VERSION=3;


// ---- profile.js ----

const SAVE_VERSION=10;
const PROFILE_STORAGE_KEY='eftd_mobile_native_profiles_v10';
const LEGACY_PROFILE_KEYS=['eftd_rift_war_profiles_v9','eftd_titans_warfronts_profiles_v8','eftd_battlefield_replay_profiles_v7','eftd_campaign_identity_profiles_v6'];
const DEV_CODE='20171107';
const SNAPSHOT_SLOT_COUNT=12;
const DIFFICULTY_RANK={easy:1,standard:2,expert:3};
const nowIso=()=>new Date().toISOString();
const clone=x=>JSON.parse(JSON.stringify(x));

function blankModeSnapshots(){return{creative:{auto:null,slots:Array.from({length:SNAPSHOT_SLOT_COUNT},()=>null)},endless:{auto:null,slots:Array.from({length:SNAPSHOT_SLOT_COUNT},()=>null)}}}
function blankProfile(slot='slot1'){
 return {saveVersion:SAVE_VERSION,profileType:'normal',slot,createdAt:nowIso(),updatedAt:nowIso(),campaign:{unlocked:1,stars:{},completedLevels:{},completedChapters:[],bestDifficultyByLevel:{}},discoveredFusions:[],codex:{towerLevels:{},enemies:[],bosses:[]},unlockedSystems:[],modeUnlocks:{creative:false,endless:false,bossrush:false,grand:false},newFlags:[],history:[],tutorialFlags:{},achievements:{},challengeRecords:{},modeSnapshots:blankModeSnapshots(),settings:{fxQuality:'auto',shake:70,damageNumbers:true,reduceFlash:false,sound:true,tutorialMode:'full',uiScale:'auto',haptic:true,cameraSensitivity:100,fpsLimit:60}};
}
function developerProfile(){const p=blankProfile('developer');p.profileType='developer';p.campaign.unlocked=40;p.modeUnlocks={creative:true,endless:true,bossrush:true,grand:true};p.devAllContent=true;return p}
function storage(){return APP_STORAGE}
function safeParse(s,fallback){try{return JSON.parse(s)}catch{return fallback}}
function normalizeSnapshots(raw){const base=blankModeSnapshots(),out={};for(const mode of ['creative','endless']){const src=raw?.[mode]||{};out[mode]={auto:src.auto||null,slots:Array.from({length:SNAPSHOT_SLOT_COUNT},(_,i)=>src.slots?.[i]||null)}}return out}
function normalizeProfile(raw,slot='slot1'){
 const base=blankProfile(slot),p={...base,...(raw||{})};
 p.saveVersion=SAVE_VERSION;p.slot=slot;p.campaign={...base.campaign,...(raw?.campaign||{})};p.campaign.stars={...(raw?.campaign?.stars||{})};p.campaign.completedLevels={...(raw?.campaign?.completedLevels||{})};p.campaign.bestDifficultyByLevel={...(raw?.campaign?.bestDifficultyByLevel||{})};p.campaign.completedChapters=[...(raw?.campaign?.completedChapters||[])];p.codex={...base.codex,...(raw?.codex||{})};p.codex.towerLevels={...(raw?.codex?.towerLevels||{})};p.codex.enemies=[...(raw?.codex?.enemies||[])];p.codex.bosses=[...(raw?.codex?.bosses||[])];p.discoveredFusions=[...(raw?.discoveredFusions||[])];p.unlockedSystems=[...(raw?.unlockedSystems||[])];p.newFlags=[...(raw?.newFlags||[])];p.history=[...(raw?.history||[])].slice(0,120);p.settings={...base.settings,...(raw?.settings||{})};p.modeUnlocks={...base.modeUnlocks,...(raw?.modeUnlocks||{})};p.tutorialFlags={...(raw?.tutorialFlags||{})};p.achievements={...(raw?.achievements||{})};p.challengeRecords={...(raw?.challengeRecords||{})};p.modeSnapshots=normalizeSnapshots(raw?.modeSnapshots);return p
}

class ProfileStore{
 constructor(){this.mem=null;this.data=this.load();this.activeType='normal'}
 load(){
  const s=storage();let raw=s?.getItem(PROFILE_STORAGE_KEY);if(!raw&&s)for(const k of LEGACY_PROFILE_KEYS){raw=s.getItem(k);if(raw)break}
  if(raw){const d=safeParse(raw,null);if(d?.profiles){const n=this.normalizeContainer(d);this.persistContainer(n);return n}}
  const d={saveVersion:SAVE_VERSION,activeSlot:'slot1',profiles:{slot1:blankProfile('slot1'),slot2:blankProfile('slot2'),slot3:blankProfile('slot3')},developer:developerProfile()};this.migrateV5(d);this.persistContainer(d);return d
 }
 normalizeContainer(d){const dev={...developerProfile(),...normalizeProfile(d.developer||{},'developer'),profileType:'developer',slot:'developer',devAllContent:true,modeUnlocks:{creative:true,endless:true,bossrush:true,grand:true}};dev.campaign={...(dev.campaign||{}),unlocked:40};return{saveVersion:SAVE_VERSION,activeSlot:['slot1','slot2','slot3'].includes(d.activeSlot)?d.activeSlot:'slot1',profiles:{slot1:normalizeProfile(d.profiles?.slot1,'slot1'),slot2:normalizeProfile(d.profiles?.slot2,'slot2'),slot3:normalizeProfile(d.profiles?.slot3,'slot3')},developer:dev}}
 migrateV5(d){
  const s=storage();if(!s)return;const legacy=safeParse(s.getItem('eftd_v5_progress')||'',null),fusions=safeParse(s.getItem('eftd_v5_fusions')||s.getItem('eftd_v42_fusions')||'',[]),codex=safeParse(s.getItem('eftd_v5_codex')||s.getItem('eftd_v42_codex')||'',{});if(!legacy&&!fusions?.length&&!Object.keys(codex||{}).length)return;
  const p=d.profiles.slot1;if(legacy){p.campaign.unlocked=Math.max(1,Math.min(20,legacy.unlocked||1));p.campaign.stars={...(legacy.stars||{})};for(const [k,v] of Object.entries(p.campaign.stars))if(v>0)p.campaign.completedLevels[k]={difficulty:'standard',stars:v,migrated:true}}
  p.discoveredFusions=[...new Set(fusions||[])];p.codex.towerLevels={...(codex||{})};p.updatedAt=nowIso()
 }
 persistContainer(d=this.data){const s=storage();if(s)try{s.setItem(PROFILE_STORAGE_KEY,JSON.stringify(d))}catch{}else this.mem=clone(d)}
 get active(){return this.activeType==='developer'?this.data.developer:this.data.profiles[this.data.activeSlot]}
 isDeveloper(){return this.activeType==='developer'}
 activateDeveloper(code){if(String(code)!==DEV_CODE)return false;this.activeType='developer';return true}
 returnToNormal(){this.activeType='normal';return this.active}
 switchSlot(slot){if(!this.data.profiles[slot])return false;this.data.activeSlot=slot;this.activeType='normal';this.persistContainer();return true}
 slotSummaries(){return Object.values(this.data.profiles).map(p=>({slot:p.slot,unlocked:p.campaign.unlocked,completed:Object.keys(p.campaign.completedLevels).length,updatedAt:p.updatedAt}))}
 getCoreProgress(){const c=this.active.campaign;return{unlocked:this.isDeveloper()?40:c.unlocked||1,stars:{...(c.stars||{})}}}
 setCoreProgress(progress){if(this.isDeveloper())return;const p=this.active;p.campaign.unlocked=Math.max(p.campaign.unlocked||1,progress?.unlocked||1);p.campaign.stars={...(p.campaign.stars||{}),...(progress?.stars||{})};this.touch()}
 getDiscoveredFusions(){return this.isDeveloper()?null:[...this.active.discoveredFusions]}
 setDiscoveredFusions(ids){if(this.isDeveloper())return;this.active.discoveredFusions=[...new Set(ids||[])];this.touch()}
 getTowerUnlocks(){if(this.isDeveloper())return{};return{...(this.active.codex.towerLevels||{})}}
 setTowerUnlocks(u){if(this.isDeveloper())return;this.active.codex.towerLevels={...(u||{})};this.touch()}
 recordEnemy(id){if(this.isDeveloper()||!id||id==='spiderling')return false;const a=this.active.codex.enemies;if(a.includes(id))return false;a.push(id);this.addNewFlag(`enemy:${id}`);this.touch();return true}
 recordBoss(id){if(this.isDeveloper()||!id)return false;const a=this.active.codex.bosses;if(a.includes(id))return false;a.push(id);this.addNewFlag(`boss:${id}`);this.touch();return true}
 recordFusion(id){if(this.isDeveloper())return false;const a=this.active.discoveredFusions;if(a.includes(id))return false;a.push(id);this.addNewFlag(`fusion:${id}`);this.touch();return true}
 addNewFlag(flag){if(this.isDeveloper()||!flag)return;const a=this.active.newFlags;if(!a.includes(flag))a.push(flag)}
 hasNewFlag(flag){return !this.isDeveloper()&&this.active.newFlags.includes(flag)}
 clearNewFlag(flag){if(this.isDeveloper())return;this.active.newFlags=this.active.newFlags.filter(x=>x!==flag);this.touch()}
 clearNewPrefix(prefix){if(this.isDeveloper())return;this.active.newFlags=this.active.newFlags.filter(x=>!x.startsWith(prefix));this.touch()}
 unlockSystem(id){if(this.isDeveloper()||!id)return false;if(this.active.unlockedSystems.includes(id))return false;this.active.unlockedSystems.push(id);this.addNewFlag(`system:${id}`);this.touch();return true}
 modeUnlocked(mode){return this.isDeveloper()||!!this.active.modeUnlocks?.[mode]}
 completeLevel(level,difficulty,stars,stats={}){
  if(this.isDeveloper())return{newModes:[]};const p=this.active,old=p.campaign.completedLevels[level],oldRank=DIFFICULTY_RANK[old?.difficulty]||0,newRank=DIFFICULTY_RANK[difficulty]||1;p.campaign.completedLevels[level]={difficulty:newRank>=oldRank?difficulty:old?.difficulty||difficulty,stars:Math.max(stars||0,old?.stars||0),completedAt:nowIso()};p.campaign.bestDifficultyByLevel[level]=newRank>=oldRank?difficulty:p.campaign.bestDifficultyByLevel[level]||old?.difficulty||difficulty;p.campaign.stars[level]=Math.max(p.campaign.stars[level]||0,stars||0);p.campaign.unlocked=Math.max(p.campaign.unlocked||1,Math.min(40,level+1));if(level%5===0&&!p.campaign.completedChapters.includes(level/5))p.campaign.completedChapters.push(level/5);
  const newModes=[];const all=Array.from({length:20},(_,i)=>p.campaign.completedLevels[i+1]).every(Boolean);if(all){for(const m of ['creative','endless','bossrush'])if(!p.modeUnlocks[m]){p.modeUnlocks[m]=true;newModes.push(m);this.addNewFlag(`mode:${m}`)}}const all40=Array.from({length:40},(_,i)=>p.campaign.completedLevels[i+1]).every(Boolean);if(all40&&!p.modeUnlocks.grand){p.modeUnlocks.grand=true;newModes.push('grand');this.addNewFlag('mode:grand')}this.touch();return{newModes}
 }
 recordBattle(entry){if(this.isDeveloper()&&entry.mode!=='creative')return;const p=this.active;p.history.unshift({id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,at:nowIso(),...entry});p.history=p.history.slice(0,120);this.touch()}
 getHistory(){return[...this.active.history]}
 settings(){return this.active.settings}
 updateSettings(partial){this.active.settings={...this.active.settings,...partial};this.touch()}
 tutorialSeen(id){return !!this.active.tutorialFlags?.[id]}
 markTutorial(id){if(!id||this.isDeveloper())return false;if(this.active.tutorialFlags[id])return false;this.active.tutorialFlags[id]=nowIso();this.touch();return true}
 unlockAchievement(id,meta={}){if(!id||this.isDeveloper())return false;if(this.active.achievements[id])return false;this.active.achievements[id]={at:nowIso(),...meta};this.addNewFlag(`achievement:${id}`);this.touch();return true}
 achievementUnlocked(id){return this.isDeveloper()||!!this.active.achievements?.[id]}
 recordChallenge(id,result){if(this.isDeveloper()||!id)return;const old=this.active.challengeRecords[id]||{wins:0,attempts:0};this.active.challengeRecords[id]={...old,attempts:(old.attempts||0)+1,wins:(old.wins||0)+(result==='victory'?1:0),lastAt:nowIso()};this.touch()}
 getModeSnapshots(mode){const m=this.active.modeSnapshots?.[mode];return m?clone(m):null}
 saveModeSnapshot(mode,slot,snapshot){if(!['creative','endless'].includes(mode))throw new Error('该模式不支持局内快照');const box=this.active.modeSnapshots[mode];const entry={...clone(snapshot),savedAt:nowIso(),slot};if(slot==='auto')box.auto=entry;else{const i=Number(slot);if(!Number.isInteger(i)||i<0||i>=SNAPSHOT_SLOT_COUNT)throw new Error('无效存档位');box.slots[i]=entry}this.touch();return clone(entry)}
 loadModeSnapshot(mode,slot){const box=this.active.modeSnapshots?.[mode];if(!box)return null;const x=slot==='auto'?box.auto:box.slots?.[Number(slot)];return x?clone(x):null}
 deleteModeSnapshot(mode,slot){const box=this.active.modeSnapshots?.[mode];if(!box)return false;if(slot==='auto')box.auto=null;else if(box.slots?.[Number(slot)]!==undefined)box.slots[Number(slot)]=null;else return false;this.touch();return true}
 touch(){this.active.updatedAt=nowIso();this.persistContainer()}
 exportActive(){return JSON.stringify({format:'Element Fusion TD v9.2 — Mobile & Native Profile',saveVersion:SAVE_VERSION,profile:clone(this.active)},null,2)}
 importToActive(text){const raw=safeParse(text,null);const candidate=raw?.profile||raw;if(!candidate||typeof candidate!=='object'||candidate.profileType==='developer')throw new Error('无效或不允许导入的存档');const slot=this.data.activeSlot;this.data.profiles[slot]=normalizeProfile(candidate,slot);this.activeType='normal';this.persistContainer();return this.active}
 resetSlot(slot=this.data.activeSlot){if(!this.data.profiles[slot])return false;this.data.profiles[slot]=blankProfile(slot);this.activeType='normal';this.persistContainer();return true}
}


