    for(const p of this.projectiles){p.life-=dt;if(p.life<=0){p.dead=true;continue}const e=this.enemies.find(x=>x.id===p.targetId&&!x.dead);if(!e){p.dead=true;continue}const dx=e.x-p.x,dy=e.y-p.y,d=Math.hypot(dx,dy)||1,step=p.speed*dt;if(step>=d){p.x=e.x;p.y=e.y;this.projectileHit(p,e);p.dead=true}else{p.x+=dx/d*step;p.y+=dy/d*step}}
