    let dmg=p.dmg;if(p.flash){e.flashHits=(e.flashHits||0)+1;const crit=Math.min(.45,.08+e.flashHits*.03);if(gameRandom()<crit){dmg*=1.8;const n=this.enemies.find(a=>!a.dead&&a.id!==e.id&&Math.hypot(a.x-e.x,a.y-e.y)<95);if(n)this.damageEnemy(n,dmg*.65,p.source,{element:'light'})}}
