// ---- camera.js ----

const cameraClamp=(v,a,b)=>Math.max(a,Math.min(b,v));
class BattlefieldCamera{
 constructor(){this.x=WORLD.w/2;this.y=WORLD.h/2;this.zoom=1;this.minZoom=1;this.maxZoom=2.35;this.tactical=false;this._beforeTactical=null}
 reset(){this.x=WORLD.w/2;this.y=WORLD.h/2;this.zoom=1;this.tactical=false;this._beforeTactical=null;return this}
 clamp(){const halfW=WORLD.w/(2*this.zoom),halfH=WORLD.h/(2*this.zoom);this.x=cameraClamp(this.x,halfW,WORLD.w-halfW);this.y=cameraClamp(this.y,halfH,WORLD.h-halfH)}
 setZoom(z,anchorScreen={x:WORLD.w/2,y:WORLD.h/2}){const before=this.screenToWorld(anchorScreen.x,anchorScreen.y);this.zoom=cameraClamp(z,this.minZoom,this.maxZoom);const after=this.screenToWorld(anchorScreen.x,anchorScreen.y);this.x+=before.x-after.x;this.y+=before.y-after.y;this.clamp();return this.zoom}
 zoomBy(factor,anchorScreen){return this.setZoom(this.zoom*factor,anchorScreen)}
 panScreen(dx,dy){this.x-=dx/this.zoom;this.y-=dy/this.zoom;this.clamp()}
 screenToWorld(sx,sy){return{x:this.x+(sx-WORLD.w/2)/this.zoom,y:this.y+(sy-WORLD.h/2)/this.zoom}}
 worldToScreen(wx,wy){return{x:WORLD.w/2+(wx-this.x)*this.zoom,y:WORLD.h/2+(wy-this.y)*this.zoom}}
 enterTactical(){if(this.tactical)return;this._beforeTactical={x:this.x,y:this.y,zoom:this.zoom};this.tactical=true;this.x=WORLD.w/2;this.y=WORLD.h/2;this.zoom=1}
 leaveTactical(){if(!this.tactical)return;const p=this._beforeTactical||{x:WORLD.w/2,y:WORLD.h/2,zoom:1};this.x=p.x;this.y=p.y;this.zoom=p.zoom;this.tactical=false;this._beforeTactical=null;this.clamp()}
 serialize(){return{x:this.x,y:this.y,zoom:this.zoom,tactical:false}}
 restore(s){if(!s)return this.reset();this.x=+s.x||WORLD.w/2;this.y=+s.y||WORLD.h/2;this.zoom=cameraClamp(+s.zoom||1,this.minZoom,this.maxZoom);this.tactical=false;this.clamp();return this}
}


// ---- platform.js ----
const nav=()=>globalThis.navigator||{};
const dims=()=>({w:Number(globalThis.innerWidth)||1280,h:Number(globalThis.innerHeight)||720});
const PLATFORM={
 isTouch:()=>globalThis.matchMedia?.('(pointer: coarse)')?.matches||(nav().maxTouchPoints||0)>0,
 isMobile:()=>{const d=dims();return /Android|iPhone|iPad|Mobile/i.test(nav().userAgent||'')||Math.min(d.w,d.h)<600},
 isStandalone:()=>globalThis.matchMedia?.('(display-mode: standalone)')?.matches||nav().standalone===true,
 isTauri:()=>!!globalThis.__TAURI_INTERNALS__||!!globalThis.__TAURI__,
 async enterFullscreen(){try{await globalThis.document?.documentElement?.requestFullscreen?.()}catch{}},
 vibrate(pattern){try{nav().vibrate?.(pattern)}catch{}},
 registerPWA(){if('serviceWorker' in nav()&&globalThis.location?.protocol!=='file:'&&!this.isTauri())nav().serviceWorker.register('./sw.js').catch(()=>{})},
 async quit(){try{const w=globalThis.__TAURI__?.window?.getCurrentWindow?.();if(w){await w.close();return true}}catch(err){console.warn('[EFTD native quit]',err)}return false},
 async onBackButtonPress(handler){try{const fn=globalThis.__TAURI__?.app?.onBackButtonPress;if(fn)return await fn(()=>handler?.())}catch(err){console.warn('[EFTD native back]',err)}return null},
 updateDeviceClasses(){const el=globalThis.document?.documentElement;if(!el)return;const d=dims(),m=this.isMobile(),touch=this.isTouch();el.classList.toggle('mobile-device',m);el.classList.toggle('touch-device',touch);el.classList.toggle('standalone-app',this.isStandalone());el.classList.toggle('tauri-app',this.isTauri());el.classList.toggle('portrait-device',m&&d.h>d.w);el.classList.toggle('landscape-device',d.w>=d.h)}
};


// ---- recovery.js ----

const RECOVERY_VERSION=1;
const RECOVERY_KEY='eftd_v92_active_battle_recovery';
function storage(){return APP_STORAGE}
class BattleRecovery{
 constructor(core,{intervalMs=2500}={}){this.core=core;this.intervalMs=intervalMs;this.timer=null;this.enabled=true;this.camera=null;this.intentional=false;this.suppressed=false;this.majorEvents=['tower:built','tower:upgrade','tower:fusion','tower:sold','skill:cast','wave:start','boss:phase','castle:hit','tower:disabled','tower:repaired','map:mechanic'];this.unsubs=[]}
 attachCamera(camera){this.camera=camera}
 eligible(){return this.enabled&&!this.suppressed&&['campaign','grand'].includes(this.core.mode)&&!this.core.victory&&!this.core.defeat&&this.core.time>0}
 read(){const s=storage();if(!s)return null;try{const x=JSON.parse(s.getItem(RECOVERY_KEY)||'null');if(!x||x.recoveryVersion!==RECOVERY_VERSION||!x.state)return null;return x}catch{return null}}
 has(){return !!this.read()}
 write(reason='rolling'){if(!this.eligible())return false;const s=storage();if(!s)return false;try{const state=this.core.exportBattleState({recovery:true});const payload={recoveryVersion:RECOVERY_VERSION,savedAt:new Date().toISOString(),reason,profileType:this.core.profileStore.isDeveloper()?'developer':this.core.profileStore.active.slot,state,camera:this.camera?.serialize?.()||null};s.setItem(RECOVERY_KEY,JSON.stringify(payload));return true}catch{return false}}
 clear(){try{storage()?.removeItem(RECOVERY_KEY)}catch{}return true}
 restore(payload=this.read()){if(!payload?.state)return false;const current=this.core.profileStore.isDeveloper()?'developer':this.core.profileStore.active.slot;if(payload.profileType!==current)return false;this.core.importBattleState(payload.state,{recovery:true});this.camera?.restore?.(payload.camera);this.arm();return true}
 start(){if(this.timer)return;for(const ev of this.majorEvents)this.unsubs.push(this.core.bus.on(ev,()=>this.write(`event:${ev}`)));this.unsubs.push(this.core.bus.on('game:victory',()=>{this.suppressed=true;this.clear()}));this.unsubs.push(this.core.bus.on('game:defeat',()=>{this.suppressed=true;this.clear()}));this.timer=setInterval(()=>this.write('rolling'),this.intervalMs);document.addEventListener('visibilitychange',()=>{if(document.hidden&&this.eligible()){this.core.paused=true;this.write('visibility-hidden')}});globalThis.addEventListener?.('pagehide',()=>{if(this.eligible())this.write('pagehide')});globalThis.addEventListener?.('beforeunload',e=>{if(this.eligible()&&!globalThis.__TAURI__){this.write('beforeunload');e?.preventDefault?.();if(e)e.returnValue=''}});}
 arm(){this.suppressed=false;this.intentional=false;return this}
 markIntentionalExit(){this.intentional=true;this.suppressed=true;this.clear();return true}
 stop(){if(this.timer)clearInterval(this.timer);this.timer=null;for(const u of this.unsubs.splice(0))try{u()}catch{}}
}


