  b.on('objective:hit',({objective,damage})=>{this.toast(`⚠ ${objective.name} 结构 -${damage}`,true);this.updateObjective();this.forceObjectiveNotice(4000)});
  b.on('objective:destroyed',({objective})=>{this.showComms('任务失败',`${objective.name} 已被摧毁`,'特殊任务目标失守，本场战役立即失败。');this.forceObjectiveNotice(7000)});
  b.on('tower:fusion',({fusion,first})=>{this.showTutorial('firstFusion');this.cancelFusion(false);if(first){this.toast(`✦ 新元素反应确认：${fusion.name}`);this.showComms('元素工坊','新配方已写入档案',`${fusion.name} 已加入融合手册与图鉴。`)}else this.toast(`融合完成：${fusion.name}`);this.renderRecipes();this.renderCodex('fusions');this.updateNewIndicators();this.updateInfo()});
  b.on('tower:upgrade',({tower,cost,evolution})=>{this.showTutorial(evolution?'firstBranch':'firstUpgrade');this.toast(`${evolution?'终极进化':'升级'}完成 · -${cost}G`);this.renderCodex(tower.kind==='fusion'?'fusions':'towers');this.updateInfo()});
  b.on('tower:sold',({value})=>{this.toast(`已出售 · +${value}G`);this.updateInfo()});b.on('boss:warning',({kind})=>{if(kind==='titanStrike')this.showTutorial('firstTowerIntegrity')});b.on('tower:disabled',({tower})=>{if(this.core.profileStore.settings().haptic!==false)this.platform?.vibrate?.(45);this.toast(`${tower.name} 结构损坏 · 已瘫痪`,true);this.showComms('攻城警报','防御塔瘫痪','结构值归零的塔会停止攻击；选中它并支付补给维修。');this.updateInfo()});b.on('tower:repaired',({tower,cost})=>{this.toast(`${tower.name} 已维修 · -${cost}G`);this.core.unlockAchievement('first_repair',{level:this.core.levelId});this.updateInfo()});b.on('enemy:siegeWarning',({enemy,target,duration})=>{this.showTutorial('firstTowerIntegrity');this.showComms('攻城预警',`${enemy.name} 锁定防御塔`,`${target.name} 将在 ${duration.toFixed(1)} 秒后受到结构打击。`)});
  b.on('tower:needsBranch',({tower})=>this.showEvolution(tower));b.on('tower:branch',({branch})=>{this.showTutorial('firstBranch');this.closeEvolution(false);this.toast(`终极进化：${branch.name}`);this.updateInfo()});
  b.on('wave:start',({wave})=>{if(wave===1)this.showTutorial('firstWave');this.updateIntel();this.updateAdvisor();this.updateWaveButtons();if(this.core.mode==='campaign'&&wave===1){const s=storyFor(this.core.levelId);this.showComms('前线指挥部',s.operation,s.objective)}});
  b.on('wave:end',({reward})=>{if(this.core.mode==='endless')this.autoSaveMode();if(reward)this.toast(`战线整备 +${reward}G`);this.updateIntel();this.updateAdvisor();this.updateWaveButtons()});
  b.on('wave:earlyBonus',({bonus})=>this.toast(`提前来袭奖励 +${bonus}G`));b.on('wave:rushBonus',({bonus})=>this.toast(`连续进攻奖励 +${bonus}G`));b.on('wave:intermission',()=>this.updateWaveButtons());b.on('wave:mode',()=>this.updateWaveButtons());
