  b.on('boss:spawn',({enemy})=>{if(this.core.profileStore.settings().haptic!==false)this.platform?.vibrate?.([45,35,70]);this.showTutorial('firstBoss');this.toast(`⚠ ${enemy.name} 进入战场`);this.showComms('紧急通讯','Boss 接触',`${enemy.name} 已进入路线。观察阶段变化，不要把全部火力压在入口。`);this.forceObjectiveNotice(7000);this.updateNewIndicators()});
