 handleKey(e){if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(e.key==='Escape'){e.preventDefault();if(this.q('evolutionModal').classList.contains('show'))this.closeEvolution();else this.enterIdle();return}if(e.code==='Space'){e.preventDefault();this.core.paused=!this.core.paused;this.q('pause').textContent=this.core.paused?'继续':'暂停';return}if(e.key.toLowerCase()==='f'){this.cycleSpeed();return}if(['1','2','3','4'].includes(e.key)){const id=Object.keys(SKILLS)[+e.key-1];if(id)this.activateSkill(id)}}
