 startMode(mode){this.renderer.camera.reset();if(!this.core.profileStore.modeUnlocked(mode)){this.toast(mode==='grand'?'完成 40 关双战役后解锁大战场行动。':'完成任意难度的 20 关主战役后解锁该模式。',true);return false}this.recovery?.markIntentionalExit?.();this.q('menuScreen').classList.remove('show');this.q('app').classList.remove('hidden');this.core.setMode(mode);this.recovery?.arm?.();if(mode==='endless')this.core.setWaveMode('auto');if(['creative','bossrush','grand'].includes(mode))this.core.setWaveMode('manual');this.core.paused=false;this.afterModeReset(mode);this.updateObjective();if(mode==='creative')this.showComms('战术实验室','创造模式已接管战场','打开顶部“实验室”，可以生成指定敌军与 Boss。');if(mode==='grand')this.showComms('大战场行动','烽火长城 · 三线总动员','20 波纵深战争；塔位绝对数增加，但三条长战线会让每一个黄金位置更稀缺。');return true}
 afterModeReset(){this.resetTransientUI();this.currentSessionId=this.core.battleSessionId;this.renderBuild();this.renderSkills();this.renderRecipes();this.updateInfo();this.updateIntel();this.updateAdvisor();this.updateModeUI();this.updateWaveButtons();this.renderMenuAccess();this.updateObjective();this.syncHUD(true);this.forceObjectiveNotice(7500)}
