 handleNativeBack(){const visible=[...document.querySelectorAll('.modal.show')].filter(m=>m.id!=='recoveryModal');if(visible.length){visible.at(-1).classList.remove('show');return true}if(!this.q('app').classList.contains('hidden')){if(!this.core.paused){this.core.paused=true;this.q('pause').textContent='继续';this.toast('已暂停');return true}this.requestExitBattle();return true}return false}
